-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Gross vs. net evaluation of offsetting misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Electronics, the auditor finds a $40,000 revenue overstatement and a $35,000 operating expense overstatement. The net effect on net income is $5,000. Under AU-C 450, when evaluating these misstatements the auditor should:', '["Assess each misstatement individually against materiality rather than netting them", "Consider only the net $5,000 income effect when comparing to overall materiality", "Disregard both since they largely offset and the net effect is immaterial", "Combine the two into a single $75,000 aggregate misstatement"]'::jsonb, 0, 'Under AU-C 450.11, the auditor evaluates misstatements individually and in aggregate. Offsetting misstatements affecting different financial statement line items is inappropriate because each may influence users'' assessment of those specific accounts. The $40,000 revenue error and $35,000 expense error must each be considered against applicable materiality levels. Netting to $5,000 would mask significant errors rather than reflecting the true magnitude of each account-level misstatement.', 'medium', 2),

-- Q2: medium / L2 — Prior-period misstatement effect on current-year accumulation
(1, 'Misstatements and Control Deficiencies', 'While auditing Granite Bay Corporation for the year ended December 31, 2025, the auditor discovers that a $60,000 prepaid insurance balance from the prior year was never expensed. The prior-year financial statements were audited by a different firm. Under AU-C 450, the auditor should:', '["Issue a qualified opinion on the current year only if the amount exceeds current-year materiality", "Include the prior-period misstatement in the current-year accumulation of identified misstatements", "Disregard the misstatement because it originated in a period audited by another firm", "Require management to restate the prior-year comparative financial statements before proceeding"]'::jsonb, 1, 'Under AU-C 450.06, the auditor accumulates misstatements identified during the audit, including the effects of uncorrected misstatements from prior periods that affect current-year financial statements. The $60,000 unamortized prepaid insurance carries forward into the current period and must be included in the aggregate evaluation. However, disregarding it because another firm audited the prior year would fail to account for its continuing effect on current financial statements.', 'medium', 2),

-- Q3: medium / L3 — Management bias in consistently low estimates
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinnacle Insurance Group, the auditor notes that management consistently selects the low end of reasonable loss reserve estimates, resulting in reserves $200,000 below the midpoint of the actuarial range. Each individual estimate falls within an acceptable range. Under AU-C 450, the auditor should:', '["Accept each estimate since it falls within the reasonable range and no individual adjustment is required", "Treat the $200,000 as a projected misstatement and extrapolate it to the full reserve population", "Evaluate whether the cumulative pattern indicates management bias that may cause a material misstatement", "Require management to adjust all estimates to the midpoint of the actuarial range"]'::jsonb, 2, 'Under AU-C 450.A18, the auditor considers indicators of possible management bias when evaluating misstatements. Even when individual estimates fall within an acceptable range, a consistent pattern of selecting assumptions favoring a particular direction may indicate bias. The cumulative effect must be evaluated as a potential misstatement. Simply accepting each estimate in isolation ignores the systematic pattern, while requiring midpoint estimates exceeds the auditor''s authority.', 'medium', 3),

-- Q4: hard / L4 — PCAOB integrated audit: compensating control assessment
(1, 'Misstatements and Control Deficiencies', 'During an integrated audit of Redwood Industries under PCAOB standards, the engagement team identifies a control deficiency in the revenue recognition process. No actual misstatement has occurred, but the control processes $50 million in annual transactions and relies on a single individual with no backup. A compensating detective control has historically caught errors. Under PCAOB AS 2201, the team should:', '["Classify the deficiency as only a significant deficiency because the compensating control has prevented actual misstatements", "Report the deficiency to management but not in the auditor''s report because no misstatement occurred", "Classify it as a control deficiency but not a significant deficiency since detective controls are operating", "Evaluate whether the compensating control sufficiently reduces the likelihood and magnitude of potential misstatement before concluding on severity"]'::jsonb, 3, 'Under PCAOB AS 2201.65-.69, the auditor evaluates severity by considering both the likelihood and magnitude of potential misstatement. Compensating controls are relevant but must be assessed for whether they adequately address the identified deficiency. The high transaction volume creates significant magnitude potential. Rather than automatically downgrading classification due to compensating controls, the auditor must evaluate whether those controls actually reduce both likelihood and magnitude sufficiently. Absence of actual misstatement alone does not preclude classification as a material weakness.', 'hard', 4),

-- Q5: medium / L3 — Segregation of duties deficiency in high-volume process
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakewood Distributors, the auditor discovers that one accounts payable clerk initiates, approves, and records vendor payments totaling $8 million annually. No compensating controls exist, and the auditor found three unauthorized payments totaling $12,000. Under AU-C 265, the auditor should most likely classify this deficiency as:', '["A material weakness because the lack of segregation of duties in a high-volume process creates a reasonable possibility of material misstatement", "A significant deficiency because the actual misstatements found were well below materiality", "A control deficiency that does not rise to significant deficiency because only $12,000 was affected", "A significant deficiency that could become a material weakness if the actual errors increase"]'::jsonb, 0, 'Under AU-C 265.A7, the severity of a control deficiency depends on the magnitude of potential misstatement, not just actual misstatement. A complete breakdown of segregation of duties over $8 million in annual transactions with no compensating controls creates a reasonable possibility of material misstatement, regardless of the relatively small actual errors detected. Classifying based on the $12,000 found would improperly focus on detected misstatements rather than the potential exposure.', 'medium', 3),

-- Q6: medium / L3 — Qualitative significance of misstatement affecting debt covenant
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northfield Manufacturing, the auditor identifies a $30,000 inventory overstatement. Performance materiality is $250,000. However, correcting this misstatement would cause the company to violate its 2.0x current ratio debt covenant with First National Bank. Under AU-C 450, the auditor should:', '["Disregard the misstatement because it is clearly below quantitative materiality", "Request management correct the misstatement but issue an unmodified opinion if they refuse", "Automatically issue an adverse opinion because a debt covenant violation is always material", "Consider the qualitative significance of the misstatement, including its effect on the debt covenant, when evaluating materiality"]'::jsonb, 3, 'Under AU-C 450.11 and .A16, the auditor considers both quantitative and qualitative factors when evaluating misstatements. A misstatement that is quantitatively immaterial may still be qualitatively significant if it affects compliance with contractual obligations such as debt covenants. The $30,000 overstatement, however, could materially affect users'' decisions by triggering a covenant violation. Ignoring qualitative factors or automatically issuing an adverse opinion would both be inappropriate responses.', 'medium', 3),

-- Q7: medium / L2 — Management representation letter and uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Bayshore Medical Center, the auditor has accumulated three uncorrected misstatements totaling $45,000, below the $300,000 materiality level. When obtaining the management representation letter under AU-C 580, the auditor should:', '["Omit any reference to uncorrected misstatements since they are below materiality", "Request that management acknowledge the uncorrected misstatements and state that their effects are immaterial to the financial statements", "Include a detailed schedule of the misstatements but not require management to assess their materiality", "Require management to certify that no misstatements exist in the financial statements"]'::jsonb, 1, 'Under AU-C 580.A10, the management representation letter should include management''s acknowledgment that the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of these items is typically attached. Omitting reference would fail to document management''s responsibility, while requiring a certification that no misstatements exist would be inaccurate given the known errors.', 'medium', 2),

-- Q8: easy / L1 — Definition of clearly trivial threshold
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what does the term "clearly trivial" mean in relation to misstatements?', '["Below 5% of overall materiality for the financial statements", "Any misstatement under $1,000 regardless of the entity''s size", "An amount the auditor designates below which misstatements need not be accumulated", "Equal to the tolerable misstatement used in audit sampling"]'::jsonb, 2, 'Under AU-C 450.05, the auditor accumulates misstatements identified during the audit other than those that are clearly trivial. Clearly trivial is an amount below which misstatements would not need to be accumulated because the auditor expects that accumulating them would not have a material effect. It is not defined as a fixed percentage or dollar amount but is set by auditor judgment. Tolerable misstatement serves a different purpose in sampling applications.', 'easy', 1),

-- Q9: medium / L3 — IT general control deficiency cascading to application controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Logistics, the auditor discovers that the IT department has no formal change management process for the ERP system. Three unauthorized program modifications were made during the year, one of which altered the automated revenue recognition calculation. Under AU-C 265, the auditor should:', '["Evaluate the IT general control deficiency for its cascading effect on all automated application controls that depend on the system", "Classify the deficiency based solely on the revenue recognition modification since only that change affected financial reporting", "Treat the lack of change management as an operational concern outside the scope of the financial statement audit", "Report the deficiency only if the revenue recognition modification caused a quantified misstatement"]'::jsonb, 0, 'Under AU-C 265.A5, the auditor considers the relationship between IT general controls and dependent application controls when evaluating deficiency severity. A failure in IT change management undermines the reliability of all automated controls that depend on the system, not just the one detected modification. Limiting the evaluation to the revenue recognition change ignores the systemic risk. IT general controls must be evaluated for financial reporting impact rather than treated as merely operational concerns.', 'medium', 3),

-- Q10: medium / L3 — Recurring misstatement indicating unaddressed control deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Retail, the auditor discovers that the same type of inventory valuation error found in the prior year has recurred, resulting in a $55,000 overstatement. Management corrected the error both years but has not addressed the underlying cause. Materiality is $400,000. Under AU-C 265, the auditor should:', '["Report only the current-year misstatement since management corrected it and it is below materiality", "Classify the issue as a control deficiency but not a significant deficiency because corrections are made each year", "Evaluate the recurring nature as an indicator that the underlying control deficiency may be a significant deficiency or material weakness", "Issue a qualified opinion because the same misstatement has occurred in two consecutive years"]'::jsonb, 2, 'Under AU-C 265.A12, a control deficiency that recurs despite being corrected each period suggests that the underlying control is not operating effectively. The repetition indicates management has not remediated the root cause, which is relevant to severity classification. The auditor must, however, evaluate whether this recurring pattern elevates the deficiency to a significant deficiency or material weakness. Simply noting the correction without addressing the recurring nature fails to properly assess severity.', 'medium', 3),

-- Q11: medium / L2 — Timing of written communication of significant deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Horizon Aerospace for the year ended December 31, 2025, the auditor identifies three significant deficiencies, including one discovered on November 15, 2025, during interim fieldwork. The audit report is dated March 5, 2026. Under AU-C 265, the written communication of significant deficiencies should be issued:', '["Within 30 days of each significant deficiency being identified during interim fieldwork", "Before interim fieldwork is completed so management can remediate before year-end", "Concurrently with the audit report date but in a separate document", "No later than 60 days following the audit report release date"]'::jsonb, 3, 'Under AU-C 265.13, the auditor should communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. While earlier communication is encouraged, particularly for deficiencies identified during interim work, the standard does not require immediate reporting upon discovery. The 60-day deadline runs from the report release date, not the report date or the date the deficiency was identified.', 'medium', 2),

-- Q12: easy / L1 — Three categories of misstatements under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'What are the three categories of misstatements recognized under AU-C 450?', '["Factual misstatements, judgmental misstatements, and projected misstatements", "Material misstatements, immaterial misstatements, and trivial misstatements", "Quantitative misstatements, qualitative misstatements, and disclosure misstatements", "Known misstatements, likely misstatements, and possible misstatements"]'::jsonb, 0, 'Under AU-C 450.A3, misstatements are categorized as factual (no doubt about the error), judgmental (differences from management estimates the auditor considers unreasonable), and projected (the auditor''s best estimate extrapolated from sampling results). The other options describe materiality thresholds or probability levels rather than the standard''s classification of misstatement types.', 'easy', 1),

-- Q13: hard / L4 — Conflicting indicators: absent preventive control with clean substantive results
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Coast Energy, the auditor identifies that the accounts receivable subledger reconciliation has never been performed. Total receivables are $15 million. However, substantive testing including confirmations and subsequent cash receipts reveals no misstatements. An independent credit department reviews all balances over $50,000 monthly. Under AU-C 265, the auditor should conclude:', '["The deficiency is not significant because substantive testing confirmed the balance is correctly stated", "The deficiency is at least a significant deficiency because a preventive control over a material account is absent, and compensating controls must be evaluated for design and operating effectiveness before classification can be reduced", "The deficiency is a material weakness because no reconciliation was performed for a $15 million balance", "The deficiency need not be reported because the credit review and substantive procedures together provide sufficient assurance"]'::jsonb, 1, 'Under AU-C 265.A7-.A8, the absence of a reconciliation control over a significant account is at minimum a significant deficiency. While compensating controls and substantive results are relevant, they do not automatically eliminate the deficiency. The auditor must evaluate whether compensating controls were specifically designed to address the deficiency and operated effectively throughout the period. Absence of detected misstatements through substantive testing does not by itself reduce severity of a control deficiency.', 'hard', 4),

-- Q14: hard / L4 — PCAOB strong indicators of material weakness
(1, 'Misstatements and Control Deficiencies', 'During an integrated audit of Atlas Financial Holdings under PCAOB standards, the auditor finds that the audit committee lacks a financial expert and met only once during the year. Management has restated prior-year financial statements due to a revenue recognition error. Under PCAOB AS 2201, these findings:', '["Constitute significant deficiencies only because no current-year misstatement has been identified", "Require the auditor to withdraw from the engagement due to inadequate corporate governance", "Represent strong indicators of a material weakness in internal control that the auditor must evaluate", "Are governance matters outside the scope of the internal control audit and should be communicated separately"]'::jsonb, 2, 'Under PCAOB AS 2201.69, restatement of previously issued financial statements is a strong indicator of a material weakness. Additionally, AS 2201.69 identifies ineffective oversight by the audit committee as another strong indicator. These factors must be evaluated in the context of the overall control environment. However, the auditor cannot dismiss them as mere governance matters or limit assessment to current-year misstatements. Strong indicators create a presumption that a material weakness exists unless the auditor has evidence to the contrary.', 'hard', 4),

-- Q15: medium / L3 — Disclosure misstatement evaluation for related-party omission
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Technologies, the auditor discovers that the footnotes omit required disclosure of a $2 million related-party transaction with the CEO''s family trust. Management argues the transaction was at arm''s length and therefore immaterial. Under AU-C 450, the auditor should:', '["Accept management''s position since arm''s-length transactions do not require special evaluation", "Treat the omission as a classification error rather than a misstatement", "Include the omission in uncorrected misstatements only if it exceeds quantitative materiality", "Evaluate the disclosure omission as a misstatement that may be qualitatively material regardless of the transaction''s terms"]'::jsonb, 3, 'Under AU-C 450.A2, misstatements include omissions or inadequate disclosures. Related-party disclosures are required under GAAP regardless of whether transactions were at arm''s length. Under AU-C 450.A16, the auditor considers qualitative factors including the nature of the item. Omission of related-party transactions with senior management is qualitatively significant because it affects users'' ability to assess governance and conflicts of interest, rather than relying solely on quantitative materiality thresholds.', 'medium', 3),

-- Q16: hard / L4 — Pattern of directional misstatements suggesting bias
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Healthcare, the auditor accumulates 12 uncorrected misstatements: seven overstate revenue by a combined $180,000, three understate expenses by $70,000, and two overstate assets by $40,000. Overall materiality is $500,000 and performance materiality is $375,000. All seven revenue misstatements resulted from management''s aggressive application of the same revenue recognition policy. The auditor should:', '["Issue an unmodified opinion because no single misstatement exceeds $50,000 and the aggregate is below materiality", "Request correction of only the revenue misstatements because they share a common cause", "Evaluate each misstatement category separately and compare each subtotal to materiality independently", "Consider both the $290,000 aggregate effect and the directional pattern favoring income overstatement as potential indicators of management bias"]'::jsonb, 3, 'Under AU-C 450.11 and .A18, the auditor evaluates uncorrected misstatements individually and in aggregate, considering both quantitative effect and qualitative characteristics such as management bias. The one-directional pattern of revenue overstatements suggests systematic bias. While the $290,000 aggregate is below $500,000 materiality, it exceeds performance materiality and the consistent direction toward income inflation requires the auditor to assess whether the misstatements, combined with possible undetected errors, could be material.', 'hard', 4),

-- Q17: easy / L1 — Purpose of the schedule of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the purpose of the auditor''s schedule of uncorrected misstatements?', '["To document all identified misstatements that management has not corrected for evaluation against materiality", "To list every error in the accounting records regardless of whether it was corrected", "To provide a detailed report to regulatory agencies about financial statement errors", "To serve as the basis for adjusting journal entries proposed to management"]'::jsonb, 0, 'Under AU-C 450.06, the auditor accumulates misstatements identified during the audit other than those that are clearly trivial. The summary of uncorrected misstatements documents items management has chosen not to correct, which the auditor evaluates individually and in aggregate to determine their effect on the financial statements. Unlike proposed adjusting entries, which cover corrections management agreed to record, this schedule focuses on items that remain in the financial statements.', 'easy', 1),

-- Q18: easy / L2 — Entity-level control environment weaknesses
(1, 'Misstatements and Control Deficiencies', 'During the audit of Brookfield Associates, the auditor learns that the company has no written code of conduct, no whistleblower hotline, and the CEO routinely overrides the approval process for large expenditures. Under AU-C 265, these conditions most likely represent:', '["Operational inefficiencies that are outside the scope of the financial statement audit", "Entity-level control deficiencies in the control environment that may indicate a material weakness", "Minor control deficiencies that should be communicated orally to management only", "Risk factors that only become deficiencies when a specific misstatement is identified"]'::jsonb, 1, 'Under AU-C 265.A5 and the COSO framework, the control environment establishes the tone at the top and is foundational to effective internal control. Absence of a code of conduct, lack of a whistleblower mechanism, and management override of controls are entity-level deficiencies that affect the entire control system. These conditions indicate a weak control environment that may constitute a material weakness, rather than requiring detection of specific misstatements before classification.', 'easy', 2),

-- Q19: medium / L2 — Tolerable misstatement exceeded in sampling results
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgemont Supply Co., the auditor tests a sample of 60 purchase transactions from a population of 4,800 and identifies $9,500 in pricing errors. Tolerable misstatement is $75,000. After projection, the estimated misstatement is $76,000. Under AU-C 530, the auditor should:', '["Accept the population because the actual errors found in the sample total only $9,500", "Automatically propose an adjustment equal to the projected misstatement of $76,000", "Conclude that the sample results do not support the planned level of assurance and consider further audit procedures", "Expand the sample by exactly 50% to reduce the projected misstatement below tolerable misstatement"]'::jsonb, 2, 'Under AU-C 530.A23-.A24, when projected misstatement exceeds tolerable misstatement, the sample results indicate unacceptable sampling risk. The auditor should consider requesting management correction, performing additional procedures, or evaluating the effect on the audit opinion. The auditor must evaluate projected amounts rather than simply accepting results based on the $9,500 sample total. Automatically adjusting or mechanically expanding the sample size are not required responses; the auditor exercises professional judgment about the appropriate next step.', 'medium', 2),

-- Q20: medium / L3 — Fair value estimate outside auditor's reasonable range
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westbrook Real Estate Trust, management values a commercial property at $12.5 million using a discounted cash flow model. The auditor''s independent estimate, using different vacancy rate assumptions, yields a range of $11.2 to $12.1 million. Under AU-C 450, the auditor should treat the difference as:', '["A factual misstatement of $400,000, calculated as the difference from the range midpoint", "Not a misstatement because management''s value is based on a recognized valuation methodology", "A projected misstatement requiring extrapolation to other real estate holdings", "A judgmental misstatement because management''s point estimate of $12.5 million exceeds the auditor''s reasonable range"]'::jsonb, 3, 'Under AU-C 450.A5, when the auditor concludes that management''s estimate is unreasonable because it falls outside the range of reasonable outcomes, the difference constitutes a judgmental misstatement. The $12.5 million exceeds the auditor''s range of $11.2 to $12.1 million, making the excess a misstatement. It is not factual because estimates inherently involve judgment, and it is not projected because it was not derived from sampling procedures.', 'medium', 3),

-- Q21: medium / L2 — Communication of deficiencies below significant deficiency level
(1, 'Misstatements and Control Deficiencies', 'During the audit of Silverline Manufacturing, the auditor identifies five control deficiencies, none of which individually or in combination rises to the level of a significant deficiency. Under AU-C 265, the auditor''s communication obligation for these deficiencies is:', '["The auditor may communicate these deficiencies to management in writing or orally, and if communicated orally should document the communication", "The auditor must communicate all identified control deficiencies in writing to those charged with governance", "The auditor has no obligation to communicate deficiencies that are below the significant deficiency level", "The auditor must include these deficiencies in the same written communication as significant deficiencies"]'::jsonb, 0, 'Under AU-C 265.12, the auditor may communicate control deficiencies that are not significant deficiencies or material weaknesses to management. This communication can be oral or written. If oral, AU-C 265.A20 indicates the auditor should document the communication. There is no requirement to communicate deficiencies below the significant deficiency threshold to those charged with governance, however, the auditor should consider whether such communication would be appropriate.', 'medium', 2),

-- Q22: medium / L2 — Remediation of material weakness during the audit period
(1, 'Misstatements and Control Deficiencies', 'During interim fieldwork in June 2025 at Pineview Financial Group, the auditor identifies a material weakness in the loan approval process. By September 2025, management redesigns the control and operates it effectively for the remaining three months of the year ended December 31, 2025. The auditor should:', '["Remove the material weakness from the written communication because it was remediated before year-end", "Evaluate the remediated control''s design and operating effectiveness and consider the period during which the weakness existed", "Report the material weakness as of year-end because it existed for more than half the audit period", "Reclassify the deficiency as a significant deficiency since it was partially remediated"]'::jsonb, 1, 'Under AU-C 265.A14, when a control deficiency is remediated during the period, the auditor evaluates both the severity of the original deficiency and the effectiveness of the new control. The three months of effective operation must be tested. The auditor also considers misstatement risk during the six months the weakness existed. Neither automatically removing the communication nor automatically reporting a material weakness is appropriate; the assessment depends on specific facts rather than applying automatic reclassification rules.', 'medium', 2),

-- Q23: hard / L4 — Multiple compensating controls with varying effectiveness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Continental Aerospace, the auditor identifies that the company lacks an automated three-way match for vendor invoices, a control processing $120 million annually. Management cites three compensating controls: monthly vendor statement reconciliations that catch 60% of errors, quarterly budget variance analysis performed at a level too high to detect invoice errors, and year-end accounts payable confirmations covering only 30% of vendors. Under AU-C 265, the auditor should:', '["Accept the compensating controls as adequate because they collectively address the missing three-way match", "Classify the deficiency as a significant deficiency since the compensating controls partially mitigate the risk", "Evaluate whether the compensating controls in combination sufficiently reduce both the likelihood and magnitude of potential misstatement to an acceptable level", "Report a material weakness only if actual misstatements from the missing control exceed materiality"]'::jsonb, 2, 'Under AU-C 265.A8, compensating controls reduce severity only to the extent they effectively address the deficiency. The auditor must evaluate each control''s precision and coverage. Budget variance analysis at too high a level and confirmations covering only 30% of vendors provide limited mitigation. The 60% detection rate still leaves significant residual risk over $120 million in transactions. Combined effectiveness determines classification rather than the number of compensating controls or the amount of detected misstatements.', 'hard', 4),

-- Q24: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'What is a deficiency in internal control as defined under auditing standards?', '["A weakness that has already caused a material misstatement in the financial statements", "Any control that does not prevent all errors from occurring in accounting records", "A condition where the external auditor cannot rely on any internal controls during the audit", "A condition where a control does not allow management or employees to prevent or detect and correct misstatements on a timely basis"]'::jsonb, 3, 'Under AU-C 265.07, a deficiency in internal control exists when the design or operation of a control does not allow management or employees, in the normal course of performing their assigned functions, to prevent or detect and correct misstatements on a timely basis. It does not require that an actual misstatement occurred, nor does it mean all errors must be prevented. The definition focuses on the control''s capability rather than its actual performance outcomes.', 'easy', 1),

-- Q25: hard / L3 — Management override with evidence of intentional manipulation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Apex Consolidated Industries, the auditor discovers that the CFO routinely processes journal entries exceeding $500,000 without the required dual-authorization review. IT logs confirm 23 such entries during the year, four of which reversed previously recorded revenue to shift earnings between quarters. Under AU-C 265, the auditor should most likely conclude that:', '["Management override of the journal entry control, combined with evidence of intentional manipulation, represents a material weakness and a potential fraud risk indicator", "The deficiency is a significant deficiency because the entries did not result in a net misstatement at year-end", "The override is a control deficiency that becomes a material weakness only if total reversed revenue exceeds materiality", "Management override is inherent in all organizations and should be considered a limitation of internal control rather than a deficiency"]'::jsonb, 0, 'Under AU-C 265.A6, management override of controls is a specific deficiency that undermines the entire control environment. When combined with evidence of intentional revenue timing manipulation, this represents both a material weakness and a potential fraud indicator under AU-C 240. The revenue reversals to shift earnings between quarters demonstrate intent, elevating severity beyond a routine override. The auditor evaluates the override pattern rather than focusing on whether a net year-end misstatement exists.', 'hard', 3),

-- Q26: easy / L1 — Primary reason for accumulating misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the primary reason auditors accumulate identified misstatements during an audit?', '["To determine the exact dollar amount of adjusting entries management must record", "To evaluate whether uncorrected misstatements, individually or in aggregate, are material to the financial statements", "To calculate the percentage of errors for regulatory reporting requirements", "To establish the basis for determining the audit fee for the engagement"]'::jsonb, 1, 'Under AU-C 450.04, the objective is to evaluate the effect of identified misstatements on the audit and the effect of uncorrected misstatements on the financial statements. Accumulating misstatements allows the auditor to assess whether the aggregate of uncorrected items could be material. The purpose is to inform the auditor''s opinion on the financial statements rather than to dictate specific adjustments or serve as a basis for fee calculation.', 'easy', 1),

-- Q27: easy / L1 — Required recipients of material weakness communications
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, to whom must the auditor communicate identified material weaknesses in writing?', '["Management only, with a copy retained in the audit working papers", "The SEC or applicable regulatory agency and the audit committee", "Those charged with governance", "The external legal counsel of the audited entity"]'::jsonb, 2, 'Under AU-C 265.11, the auditor is required to communicate in writing to those charged with governance significant deficiencies and material weaknesses identified during the audit. Those charged with governance typically include the audit committee or full board of directors. There is no general requirement under AU-C 265 to communicate these findings to regulatory agencies or legal counsel, although other standards or regulations may impose additional reporting requirements.', 'easy', 1),

-- Q28: easy / L1 — Distinction between corrected and uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the distinction between corrected and uncorrected misstatements in the audit process?', '["Corrected misstatements are omitted from audit documentation while uncorrected misstatements are fully documented", "Corrected misstatements are recorded by management during the audit, while uncorrected misstatements remain and must be evaluated for aggregate materiality", "Corrected misstatements require communication to those charged with governance, while uncorrected misstatements do not", "There is no distinction because all identified misstatements receive identical treatment"]'::jsonb, 1, 'Under AU-C 450.05-.06, corrected misstatements are those management records as adjustments during the audit, while uncorrected misstatements are those management chooses not to correct. The auditor must evaluate the aggregate effect of uncorrected misstatements to determine whether they are material to the financial statements. Both categories are documented, but uncorrected misstatements require specific evaluation against materiality and may affect the auditor''s opinion.', 'easy', 1),

-- Q29: medium / L2 — Documentation requirements for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Heritage Construction Group, the engagement partner requests documentation supporting the team''s evaluation of misstatements. Under AU-C 450, the audit documentation for misstatement evaluation should include:', '["The amount below which misstatements are considered clearly trivial, all accumulated misstatements, and the auditor''s conclusion on whether uncorrected misstatements are material", "Only the list of uncorrected misstatements that exceed 10% of overall materiality", "A summary of misstatements communicated to management without the auditor''s materiality conclusion", "The total dollar amount of all misstatements found, aggregated into a single figure"]'::jsonb, 0, 'Under AU-C 450.14-.15, audit documentation must include the clearly trivial threshold, accumulated misstatements and whether they were corrected, the auditor''s evaluation of whether uncorrected misstatements are material, and the basis for that conclusion. Documentation limited to items above a percentage threshold or presented as a single aggregate figure would fail to meet the standard''s requirements, unlike a comprehensive schedule that enables transparent evaluation of individual and aggregate effects.', 'medium', 2),

-- Q30: easy / L1 — Severity hierarchy of control deficiencies
(1, 'Misstatements and Control Deficiencies', 'What is the correct hierarchy of control deficiency severity from least to most severe under AU-C 265?', '["Significant deficiency, control deficiency, material weakness", "Control deficiency, significant deficiency, material weakness", "Material weakness, significant deficiency, control deficiency", "Minor deficiency, moderate deficiency, major deficiency"]'::jsonb, 1, 'Under AU-C 265.07, the hierarchy from least to most severe is: control deficiency (the baseline), significant deficiency (important enough to merit attention by those charged with governance), and material weakness (reasonable possibility that a material misstatement will not be prevented or detected and corrected). Unlike terms such as minor, moderate, and major, AU-C 265 uses these three specific severity levels.', 'easy', 1)
;

COMMIT;
